INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch13$PT145-S4-Q7$batch13$, 145, 4, 7, $batch13$Role$batch13$, $batch13$It is widely believed that the most environmentally sensible thing to do is to buy food from local farmers whenever it is available. But the distance that food travels turns out to be only a small part of its environmental impact. Certain foods can be produced with far less impact in some places rather than others. So, sometimes it is environmentally preferable to buy food that is not produced locally, rather than buy locally produced food.$batch13$, $batch13$The claim that the most environmentally sensible thing to do is to buy food from local farmers whenever it is available plays which one of the following roles in the argument?$batch13$, $batch13$D$batch13$, true, $batch13$Batch 13; question text from local bank.$batch13$ FROM lr_sections s WHERE s.preptest=145 AND s.section=4 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch13$PT145-S4-Q7$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$A$batch13$, $batch13$It is a principle upon which the reasoning in the argument is based.$batch13$, $batch13$Wrong Role$batch13$, false FROM lr_questions q WHERE q.qid=$batch13$PT145-S4-Q7$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$A$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$B$batch13$, $batch13$It is a general principle that is used to support a particular activity that falls under it.$batch13$, $batch13$Wrong Role$batch13$, false FROM lr_questions q WHERE q.qid=$batch13$PT145-S4-Q7$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$B$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$C$batch13$, $batch13$It is a general principle that is used to reject a particular activity that is not compatible with it.$batch13$, $batch13$Wrong Role$batch13$, false FROM lr_questions q WHERE q.qid=$batch13$PT145-S4-Q7$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$C$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$D$batch13$, $batch13$It is a view that is rejected by the argument.$batch13$, $batch13$Correct$batch13$, true FROM lr_questions q WHERE q.qid=$batch13$PT145-S4-Q7$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$D$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$E$batch13$, $batch13$It is the conclusion of the argument.$batch13$, $batch13$Wrong Role$batch13$, false FROM lr_questions q WHERE q.qid=$batch13$PT145-S4-Q7$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$E$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch13$PT145-S4-Q7$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch13$Opposing Point$batch13$, $batch13$It is widely believed that the most environmentally sensible thing is to buy food from local farmers whenever it is available.$batch13$), (1, $batch13$Conclusion$batch13$, $batch13$Sometimes it is environmentally better to buy food that is not produced locally.$batch13$), (2, $batch13$Evidence$batch13$, $batch13$The distance food travels is only a small part of its environmental impact. Some foods can be produced with far less impact in some places than in others.$batch13$), (3, $batch13$Evaluate$batch13$, $batch13$"It is widely believed" sets up a view, and "But" turns against it. The conclusion says non-local food is sometimes better, which contradicts "whenever it is available". So the claim in the stem is the view the argument rejects.$batch13$), (4, $batch13$Goal$batch13$, $batch13$Find the answer that calls the claim a view the argument rejects.$batch13$)) v(position,label,body) WHERE q.qid=$batch13$PT145-S4-Q7$batch13$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch13$A$batch13$, $batch13$The reasoning isn't based on this principle. It argues against it.$batch13$), ($batch13$B$batch13$, $batch13$The claim isn't used to support anything. The argument rejects it.$batch13$), ($batch13$C$batch13$, $batch13$The claim isn't used to reject an activity. The argument rejects the claim itself.$batch13$), ($batch13$D$batch13$, $batch13$"Widely believed" introduces it and "But" attacks it. The conclusion says buying non-local food is sometimes the better choice, which is the opposite.$batch13$), ($batch13$E$batch13$, $batch13$The conclusion is the last sentence, and it contradicts this claim.$batch13$)) v(letter,body) WHERE q.qid=$batch13$PT145-S4-Q7$batch13$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
